for c in "uname -r" "cat /etc/os-release" "nft --version" "nft -j list ruleset" "iptables -V" "ip -j addr show" "ip -j route show default" "ip -j -6 route show default" "ip -j link show" "ss -Hlntup" "systemctl is-enabled nftables" "systemctl is-active nftables" "systemctl is-active firewalld" "netbird status --json" "netbird status" "sysctl -n net.ipv4.ip_forward net.ipv6.conf.all.forwarding" "systemd-run --version"; do echo "### $c"; timeout 10 sh -c "$c" 2>&1; echo "### rc=$?"; done
echo "### tools"; for t in nft iptables iptables-legacy iptables-nft iptables-save iptables-legacy-save ipset netbird systemd-run systemctl rc-service at crontab curl; do command -v $t || echo "missing:$t"; done; echo "### rc=0"
